<section class="section product-detail"><div class="container"><nav class="breadcrumb"><a href="<?=e(url('products'))?>">Products</a><span>/</span><a href="<?=e(url('products/'.$product['category_slug']))?>"><?=e($product['category_name'])?></a></nav><div class="row g-5"><div class="col-lg-5"><div class="detail-image"><img src="<?=e(upload_url($product['main_image']))?>" alt="<?=e($product['name'])?>"></div></div><div class="col-lg-7"><span class="eyebrow"><?=e($product['category_name'])?></span><h1><?=e($product['name'])?></h1><?php if($product['product_code']):?><p class="product-code">Product code: <?=e($product['product_code'])?></p><?php endif;?><p class="lead text-secondary"><?=e($product['short_description'])?></p><div class="d-flex flex-wrap gap-3"><a class="btn btn-primary btn-lg" href="<?=e(url('request-quote?product='.urlencode($product['slug'])))?>">Request Quote</a><?php if(!empty($settings['whatsapp'])):?><a class="btn btn-outline-primary btn-lg" target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D+/','',$settings['whatsapp']))?>?text=<?=rawurlencode("Hello L2 Chemicals,\nI am interested in {$product['name']}.\nPlease share details.")?>"><i class="fa-brands fa-whatsapp"></i> WhatsApp Enquiry</a><?php endif;?><?php if(!empty($product['official_url'])):?><a class="btn btn-outline-primary btn-lg" target="_blank" rel="noopener noreferrer" href="<?=e($product['official_url'])?>"><i class="fa-solid fa-arrow-up-right-from-square"></i> Official Website</a><?php endif;?></div></div></div><div class="detail-sections"><?php foreach(['full_description'=>'Overview','features'=>'Features','benefits'=>'Benefits','applications'=>'Applications','technical_information'=>'Technical Information','packaging_information'=>'Packaging Information'] as $field=>$heading):?><?php if(!empty($product[$field])):?><section><h2><?=e($heading)?></h2><p><?=nl2br(e($product[$field]))?></p></section><?php endif;?><?php endforeach;?><?php if($product['documents']):?><section><h2>Documents</h2><div class="document-list"><?php foreach($product['documents'] as $document):?><a href="<?=e(url($document['file_path']))?>" target="_blank" rel="noopener"><i class="fa-regular fa-file-pdf"></i><?=e($document['title'])?></a><?php endforeach;?></div></section><?php endif;?></div></div></section>
